enum {
    LMB_ABI_VERSION = 1,
    LMB_FRAME_HEADER_SIZE = 8,
    LMB_FRAME_VERSION = 1,
    LMB_MAX_RAW_BYTES = 4096,
    LMB_MAX_FRAME_BYTES = 4104,
    LMB_MAX_NAME_BYTES = 256,
    LMB_ERROR_MSG_CAP = 1024,
    LMB_MAX_MSG_LEN = 1023
};

enum lmb_domain_v1 {
    LMB_DOMAIN_NONE = 0,
    LMB_DOMAIN_POSIX = 1,
    LMB_DOMAIN_LIBBPF = 2,
    LMB_DOMAIN_KERNEL = 3,
    LMB_DOMAIN_BRIDGE = 4
};

enum lmb_generic_domain_v1 {
    LMB_GENERIC_DOMAIN_NONE = 0,
    LMB_GENERIC_DOMAIN_POSIX = 1,
    LMB_GENERIC_DOMAIN_LIBBPF = 2,
    LMB_GENERIC_DOMAIN_KERNEL = 3,
    LMB_GENERIC_DOMAIN_BRIDGE = 4
};

struct lmb_attach_options_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_span_v1 program;
    uint32_t family;
    uint32_t flags;
    struct lmb_span_v1 target_a;
    struct lmb_span_v1 target_b;
    uint64_t _reserved;
};

struct lmb_attach_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_bytes_v1 program;
    uint32_t kind;
    uint32_t flags;
    struct lmb_bytes_v1 target_a;
    struct lmb_bytes_v1 target_b;
};

struct lmb_buffer_options_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_span_v1 ring;
    uint32_t max_raw_bytes;
    uint32_t stage_slots;
    uint32_t flags;
    uint32_t _reserved;
};

struct lmb_bytes_v1 {
    const uint8_t *ptr;
    uint32_t len;
    uint32_t _pad;
};

struct lmb_error_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    uint32_t operation;
    uint32_t domain;
    int32_t code;
    uint32_t msg_len;
    uint8_t message[LMB_ERROR_MSG_CAP];
};

struct lmb_generic_error_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    uint32_t operation;
    uint32_t domain;
    int32_t code;
    uint32_t msg_len;
    uint8_t message[LMB_GENERIC_ERROR_MSG_CAP];
};

struct lmb_map_info_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    uint32_t type;
    uint32_t key_size;
    uint32_t value_size;
    uint32_t max_entries;
    uint32_t map_flags;
    uint32_t num_cpus;
    uint32_t stride;
    uint32_t _reserved;
};

struct lmb_name_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_bytes_v1 name;
};

struct lmb_object_options_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_span_v1 name;
    struct lmb_span_v1 custom_btf;
    uint32_t log_level;
    uint32_t flags;
    uint64_t log_capacity;
    uint64_t _reserved;
};

struct lmb_options_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_bytes_v1 ring;
    uint32_t max_raw_bytes;
    uint32_t stage_slots;
    uint32_t flags;
    uint32_t _reserved;
};

struct lmb_program_info_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    uint32_t prog_type;
    uint32_t attach_type;
    uint64_t insn_count;
    uint64_t generation;
    uint32_t autoload;
    uint32_t _pad0;
    struct lmb_out_span_v1 log;
    uint64_t log_actual;
    uint32_t log_truncated;
    uint32_t _reserved;
};

struct lmb_program_options_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_span_v1 program;
    struct lmb_span_v1 attach_target;
    uint32_t autoload;
    uint32_t flags;
};

struct lmb_program_test_options_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    struct lmb_span_v1 data_in;
    struct lmb_out_span_v1 data_out;
    struct lmb_span_v1 ctx_in;
    struct lmb_out_span_v1 ctx_out;
    uint64_t repeat;
    uint64_t flags;
};

struct lmb_program_test_result_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    uint32_t retval;
    uint32_t _pad;
    uint64_t data_actual;
    uint64_t ctx_actual;
    uint64_t duration_ns;
};

struct lmb_span_v1 {
    const uint8_t *ptr;
    uint64_t len;
};

struct lmb_stats_v1 {
    uint32_t abi_version;
    uint32_t struct_size;
    uint64_t received;
    uint64_t delivered;
    uint64_t staged;
    uint64_t malformed;
    uint64_t dropped;
    int32_t last_error;
    uint32_t _reserved;
};
